    74  bool fr_dns_packet_ok(uint8_t const *packet, size_t packet_len, bool query)
    75  {
    76          if (packet_len <= DNS_HDR_LEN) {
    77                  return false;
    78          }
    79
    80          /*
    81           *      query=0, response=1
    82           */
    83          if (((packet[2] & 0x80) == 0) != query) {
    84                  return false;
    85          }
    86
    87          if (query) {
    88                  /*
    89                   *      There should be at least one query, and no replies in the query!
    90                   */
    91                  if (fr_net_to_uint16(packet + 4) == 0) {
    92                          return false;
    93                  }
    94                  if (fr_net_to_uint16(packet + 6) != 0) {
    95                          return false;
    96                  }
    97                  if (fr_net_to_uint16(packet + 8) != 0) {
    98                          return false;
    99                  }
   100
   101                  // additional records can exist!
   102          } else {
   103                  /*
   104                   *      Replies _usually_ copy the query.  But not
   105                   *      always And replies can have zero or more answers.
   106                   */
   107          }
   108
   109          return true;
   110  }
